function Toolbar({query,setQuery,label,action}){return <div className="toolbar"><div className="search"><Search size={17}/><input aria-label="Buscar registros" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar…"/></div><button className="primary" onClick={action}><Plus size={17}/>{label}</button></div>}
function Tabs({options,value,setValue}){return <div className="tabs">{options.map(o=><button key={o} className={value===o?'selected':''} onClick={()=>setValue(o)}>{o}</button>)}</div>}
function FormActions({close,label='Guardar'}){return <div className="form-actions"><button type="button" onClick={close}>Cancelar</button><button className="primary" type="submit"><Check size={16}/>{label}</button></div>}
function DocumentForm({db,side,doc,initialKind,fixedKind,save,close}){
 const [kind,setKind]=useState(doc?.kind||initialKind||(side==='sale'?'Pedido':'Pedido de compra')),[contact,setContact]=useState(doc?.contact??('')),[warehouse,setWarehouse]=useState(doc?.warehouse??(db.warehouses[0]?.id||'')),[currency,setCurrency]=useState(doc?.currency??('USD')),[rate,setRate]=useState(doc?.rate??(db.rate||'')),[date,setDate]=useState(doc?.date??(D.today())),[due,setDue]=useState(doc?.due??(D.today())),[condition,setCondition]=useState(doc?.condition??('Contado')),[lines,setLines]=useState(doc?.lines??([{product:'',qty:1,price:0}]));
 const [notes,setNotes]=useState(doc?.notes||'');
 const total=D.round(lines.reduce((s,l)=>s+D.round(Number(l.qty)*Number(l.price)),0));
 function lineChange(i,key,v){setLines(ls=>ls.map((l,j)=>{if(j!==i)return l;const next={...l,[key]:v};if(key==='product'){const p=db.products.find(p=>p.id===v);let price=side==='sale'?p?.price:p?.cost;if(p?.currency!==currency){price=Number(rate)>0?(currency==='USD'?price/Number(rate):price*Number(rate)):0}next.price=D.round(price||0);next.hasSerial=!!p?.hasSerial;next.serials=[]}return next}))}
 return <form onSubmit={e=>{e.preventDefault();save({side,kind,contact,warehouse,currency,rate,date,due,condition,lines,notes})}}><fieldset className="form-grid invoice-fields" disabled={kind==='Venta'}><Field label="Tipo de documento"><select disabled={!!doc||fixedKind} value={kind} onChange={e=>setKind(e.target.value)}>{(side==='sale'?(initialKind==='Venta'||doc?.kind==='Venta'?['Venta']:['Presupuesto','Pedido','Nota de entrega']):['Pedido de compra']).map(k=><option key={k} value={k}>{k==='Pedido'?'Orden de venta':k==='Venta'?'Factura por orden de venta':k}</option>)}</select></Field><ContactPicker db={db} side={side} value={contact} onChange={id=>{setContact(id);const c=db.contacts.find(c=>c.id===id);const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+(c?.days||0));setDue(d.toISOString().slice(0,10))}}/><Select label="Depósito *" value={warehouse} onChange={e=>setWarehouse(e.target.value)} options={db.warehouses}/><Field label="Moneda"><select value={currency} onChange={e=>{setCurrency(e.target.value);setLines([{product:'',qty:1,price:0}])}}><option>USD</option><option value="VES">Bs.</option></select></Field><Field label="Fecha" type="date" value={date} onChange={e=>setDate(e.target.value)} required/><Field label="Vencimiento" type="date" value={due} min={date} onChange={e=>setDue(e.target.value)} required/><Field label="Tasa aplicada (Bs./USD)" type="number" min="0" step="0.0001" value={rate} onChange={e=>setRate(e.target.value)}/><Field label="Condición"><select value={condition} onChange={e=>setCondition(e.target.value)}><option>Contado</option><option>Crédito</option></select></Field></fieldset>{kind==='Venta'&&<div className="alert">Los datos comerciales se conservan de la orden. Completá los seriales y las observaciones para generar la factura.</div>}<h3>Productos</h3>{lines.map((l,i)=><div className="line" key={i}><div className="line-number"><small>Línea</small><strong>{i+1}</strong></div><ProductPicker db={db} warehouse={warehouse} value={l.product} disabled={kind==='Venta'} line={i+1} onChange={id=>lineChange(i,'product',id)}/><Field disabled={kind==='Venta'} label="Cantidad" type="number" min="0.01" step="0.01" value={l.qty} onChange={e=>lineChange(i,'qty',e.target.value)} required/><Field disabled={kind==='Venta'} label={`Precio (${currency})`} type="number" min="0" step="0.01" value={l.price} onChange={e=>lineChange(i,'price',e.target.value)} required/><strong>{money(D.round(l.qty*l.price),currency)}</strong>{['Venta','Nota de entrega'].includes(kind)&&(l.hasSerial||db.products.find(p=>p.id===l.product)?.hasSerial)&&<Field label={`Seriales · ${l.qty} unidades (uno por línea)`}><textarea aria-label={`Seriales producto ${i+1}`} rows="3" value={Array.isArray(l.serials)?l.serials.join('\n'):l.serials||''} onChange={e=>lineChange(i,'serials',e.target.value)}/></Field>}<button type="button" className="icon" aria-label="Quitar producto" disabled={kind==='Venta'||lines.length===1} onClick={()=>setLines(ls=>ls.filter((_,j)=>j!==i))}><X size={18}/></button></div>)}<button type="button" disabled={kind==='Venta'} onClick={()=>setLines([...lines,{product:'',qty:1,price:0}])}><Plus size={16}/> Agregar producto</button><Field label="Observaciones"><textarea value={notes} onChange={e=>setNotes(e.target.value)} rows="3"/></Field>{kind==='Nota de entrega'&&<div className="alert">Constancia de entrega: no descuenta stock ni genera deuda. Registrá la venta para contabilizar la salida y el saldo.</div>}<div className="total">Total comercial <strong>{money(total,currency)}</strong></div><p className="hint">{doc?.status==='Confirmado'?'Se conserva el estado confirmado.':'Se guarda como borrador.'} La confirmación se realiza desde el listado. Importes sin cálculo fiscal.</p><FormActions close={close} label={kind==='Venta'?'Generar factura':doc?'Guardar cambios':'Guardar borrador'}/></form>
}
createRoot(document.getElementById('root')).render(<App/>);

function FormActionsDelete({cancel,remove}){return <div className="form-actions"><button onClick={cancel}>Cancelar</button><button className="danger" onClick={remove}>Eliminar borrador</button></div>}

function InvoiceNoteForm({db,order,kind,save,close}){
 const [query,setQuery]=useState(''),[invoice,setInvoice]=useState('');
 const invoices=db.documents.filter(d=>d.kind==='Venta'&&d.status==='Confirmado'&&d.source===order.id);
 const selected=invoices.find(d=>d.id===invoice);
 return <form onSubmit={e=>{e.preventDefault();save(Object.fromEntries(new FormData(e.currentTarget)))}}><p>Orden {order.number} · {kind}</p><Field label="Buscar factura" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Número de factura o cliente"/><Field label="Factura de origen *"><select required name="invoice" value={invoice} onChange={e=>setInvoice(e.target.value)}><option value="">Seleccionar factura…</option>{invoices.filter(d=>d.id===invoice||(d.number+' '+db.contacts.find(c=>c.id===d.contact)?.name).toLowerCase().includes(query.toLowerCase())).map(d=><option key={d.id} value={d.id}>{d.number} · {db.contacts.find(c=>c.id===d.contact)?.name}</option>)}</select></Field>{!invoices.length&&<div className="alert">Esta orden todavía no tiene una factura confirmada.</div>}{selected&&<p>Saldo: {money(D.balance(db,selected),selected.currency)}</p>}<Field label="Fecha *" name="date" type="date" defaultValue={D.today()} min={selected?.date} required/><Field label={'Importe '+(selected?.currency||'')} name="amount" type="number" min="0.01" step="0.01" required/><Field label="Motivo *"><textarea name="reason" required rows="3"/></Field><p className="hint">Ajuste comercial del saldo de la factura. No modifica inventario ni registra devoluciones físicas.</p><FormActions close={close} label={'Generar '+kind.toLowerCase()}/></form>;
}

function ContactPicker({db,side,value,onChange}){
 const [query,setQuery]=useState(''),[visible,setVisible]=useState(false);
 const normalize=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
 const options=db.contacts.filter(c=>(c.kind==='Ambos'||c.kind===(side==='sale'?'Cliente':'Proveedor'))&&[c.name,c.rif].some(s=>normalize(s).includes(normalize(query))));
 const selected=db.contacts.find(c=>c.id===value);
 const choose=c=>{onChange(c.id);setQuery('');setVisible(false)};
 return <div className="field contact-picker"><span>{side==='sale'?'Buscar cliente por RIF o nombre *':'Buscar proveedor por RIF o nombre *'}</span><div className="contact-search"><input aria-label="Buscar por RIF o nombre" value={query} placeholder="Escribí RIF o nombre…" onChange={e=>{setQuery(e.target.value);setVisible(true)}} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();if(options.length===1)choose(options[0]);else setVisible(true)}if(e.key==='Escape')setVisible(false)}}/><button type="button" aria-label="Buscar cliente con lupa" onClick={()=>setVisible(v=>!v)}><Search size={18}/></button></div>{visible&&<div className="contact-results" role="list" aria-label="Resultados de clientes">{options.slice(0,30).map(c=><button type="button" role="listitem" key={c.id} onClick={()=>choose(c)}><strong>{c.name}</strong><small>{c.rif}</small></button>)}{!options.length&&<p>No hay coincidencias.</p>}{options.length>30&&<p>Escribí más datos para acotar la búsqueda.</p>}</div>}{selected&&<div className="selected-contact"><strong>{selected.name}</strong><small>{selected.rif} · {selected.contactPerson||selected.phone||'Sin contacto'}</small></div>}{!selected&&<small>Seleccioná un cliente de los resultados.</small>}</div>;
}

function ProductPicker({db,warehouse,value,onChange,disabled,line}){
 const [query,setQuery]=useState(''),[visible,setVisible]=useState(false);
 const normalize=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const options=db.products.filter(p=>p.active!==false&&normalize(p.sku+' '+p.name).includes(normalize(query)));
 const selected=db.products.find(p=>p.id===value);
 const choose=p=>{onChange(p.id);setQuery('');setVisible(false)};
 return <div className="field product-picker"><span>Producto · SKU o nombre</span><input disabled={disabled} aria-label={'Buscar producto línea '+line} placeholder="Escribí SKU o nombre…" value={visible?query:selected?selected.sku+' · '+selected.name:query} onFocus={()=>{if(!disabled)setVisible(true)}} onChange={e=>{setQuery(e.target.value);setVisible(true)}} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();if(options.length===1)choose(options[0]);else setVisible(true)}if(e.key==='Escape')setVisible(false)}}/>{visible&&!disabled&&<div className="product-results" role="list" aria-label={'Productos línea '+line}>{options.slice(0,20).map(p=><button key={p.id} type="button" onClick={()=>choose(p)}><strong>{p.sku} · {p.name}</strong><small>Stock: {D.stock(db,p.id,warehouse)} {p.unit}</small></button>)}{!options.length&&<p>No hay coincidencias.</p>}{options.length>20&&<p>Escribí más datos para acotar la búsqueda.</p>}<button type="button" onClick={()=>setVisible(false)}>Cerrar búsqueda</button></div>}</div>;
}

function ReceiptSelector({db,choose}){const [query,setQuery]=useState('');const orders=db.documents.filter(d=>d.kind==='Pedido de compra'&&d.status==='Confirmado'&&(d.number+' '+db.contacts.find(c=>c.id===d.contact)?.name).toLowerCase().includes(query.toLowerCase()));return <><Field label="Buscar pedido o proveedor" value={query} onChange={e=>setQuery(e.target.value)}/><Table headers={['Pedido','Proveedor','Fecha','Acción']} rows={orders.map(d=>[d.number,db.contacts.find(c=>c.id===d.contact)?.name,d.date,<button onClick={()=>choose(d)}>Recibir mercancía</button>])} empty="No hay pedidos confirmados pendientes de recepción"/></>}
